class Solution:

	def maximumSumRectangle(self, R, C, M):
		pre = [[0] * (C + 1) for i in range(0, R)]
		ans = -1000000000000000
		for i in range(0, R):
			for j in range(0, C):
				pre[i][j + 1] += pre[i][j] + M[i][j]
				ans = max(ans, M[i][j])
		for i in range(0, C):
			for j in range(i, C):
				(sy, ey) = (i, j + 1)
				ca = -1000000000000000
				mtt = -1000000000000000
				for k in range(0, R):
					cv = pre[k][ey] - pre[k][sy]
					mtt = max(cv, cv + mtt)
					ca = max(ca, mtt)
				ans = max(ans, ca)
		return ans
